//! JSON parse benchmark: serde_json vs sonic-rs vs simd-json.
//!   cargo run -q --release -p smash-ext --example json-bench

use std::time::Instant;

use smash_core::{Action, Row, Tone, View};

fn bench(mut parse: impl FnMut(&[u8]), bytes: &[u8], iters: usize, name: &str) {
    for _ in 0..iters / 10 {
        parse(bytes);
    }
    let start = Instant::now();
    for _ in 0..iters {
        parse(bytes);
    }
    let elapsed = start.elapsed().as_secs_f64();
    let ns = elapsed * 1e9 / iters as f64;
    let mbs = bytes.len() as f64 * iters as f64 / elapsed / 1e6;
    println!(
        "{name:22} {ns:9.1} ns/op {mbs:8.1} MB/s  ({} B)",
        bytes.len()
    );
}

